parameters.jsCode:
const payload = $input.first().json.body || $input.first().json;

const surveyId = payload.survey_id || "SURVEY-UNKNOWN";
const status = payload.status || "APPROVED_AUTO_PERMIT";
const riskScore = payload.risk_score || 0;
const clearanceCode = payload.clearance_pass_code || ("SEAL-ODC-" + Date.now().toString(36).toUpperCase());
const distanceKm = payload.total_distance_km || 0;
const feeInr = payload.total_statutory_fee_inr || 0;
const clientId = payload.client_id || "SEALAND_CLIENT";

const clearanceMemo = `=================================================================
SEALAND LOGISTICS GROUP - SPECIALIZED PROJECT CARGO DIVISION
OFFICIAL ODC/OOG ROUTE CLEARANCE CERTIFICATE & PERMIT MEMORANDUM
=================================================================
Survey Reference  : ${surveyId}
Clearance Pass Code: ${clearanceCode}
Client Division   : ${clientId}
Corridor Distance : ${distanceKm} km
Composite Risk    : ${riskScore} / 100
Clearance Decision: ${status}
Total Statutory Fee: INR ${Number(feeInr).toLocaleString()}

STATUTORY ESCORT & TRAFFIC POLICE COMPLIANCE:
- Front Pilot Vehicle with amber revolving strobe mandatory.
- Rear Safety Escort Vehicle equipped with retro-reflective chevrons.
- Night transit restrictions apply in designated state jurisdictions.

AUDIT & VERIFICATION:
Deterministic Zero-LLM constraint validation passed.
Verified against Ministry of Road Transport & Highways (MoRTH) standards.
=================================================================`;

return [{
  json: {
    survey_id: surveyId,
    clearance_pass_code: clearanceCode,
    status: status,
    risk_score: riskScore,
    clearance_memo: clearanceMemo,
    notification_sent_to: ["dispatch@sealandlogisticsgroup.com", "projects@sealandlogisticsgroup.com"],
    dispatched_at: new Date().toISOString()
  }
}];

parameters.responseBody:
={{ JSON.stringify({
  success: true,
  event: "OOG_CLEARANCE_NOTIFICATION_DISPATCHED",
  survey_id: $json.survey_id,
  clearance_pass_code: $json.clearance_pass_code,
  status: $json.status,
  dispatched_at: $json.dispatched_at,
  memo_preview: $json.clearance_memo
}) }}
